styles:
/* Aylık Sayım Sonucu — modern detay sayfası */
.ass-page {
  --ass-primary: #4557a3;
  --ass-primary-mid: #586495;
  --ass-accent: #5b6fd6;
  --ass-muted: #94a3b8;
  --ass-label: #64748b;
  --ass-text: #1e293b;
  --ass-border: #e2e8f0;
  --ass-surface: #ffffff;
  --ass-soft: #f8fafc;
  --ass-shadow: 0 4px 24px rgba(69, 87, 163, 0.08);
  --ass-radius: 16px;
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 100%;
  min-height: 100%;
  margin: 0;
  padding: 1.25rem 1rem 2.5rem;
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  color: var(--ass-text);
  background: linear-gradient(180deg, #f8fafc 0%, #eef2ff 100%);
  box-sizing: border-box;
}

@media (min-width: 768px) {
  .ass-page {
    padding: 1.5rem 1.5rem 2.75rem;
  }
}

@media (min-width: 1200px) {
  .ass-page {
    padding: 1.75rem 2rem 3rem;
  }
}

.ass-page *,
.ass-page *::before,
.ass-page *::after {
  box-sizing: border-box;
}

/* Toolbar */
.ass-page .ass__toolbar {
  order: -20;
  flex: 0 0 auto;
  width: 100% !important;
  max-width: 100% !important;
  margin: 0 0 1rem 0 !important;
  padding: 0 !important;
}

.ass-page .ass__toolbar > .row,
.ass-page .ass__toolbar .row {
  display: flex !important;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 0.65rem;
  width: 100% !important;
  margin: 0 !important;
}

.ass-page .ass__toolbar .col,
.ass-page .ass__toolbar [class*='col-'] {
  flex: 0 1 auto;
  width: auto !important;
  max-width: none;
  padding: 0 !important;
}

.ass-page .ass__toolbar .col:last-child,
.ass-page .ass__toolbar [class*='col-']:last-child {
  margin-left: auto;
}

.ass-page .ass__toolbar .p-button {
  border-radius: 10px;
  font-weight: 600;
  min-height: 2.5rem;
}

.ass-page .ass__toolbar .p-button-success,
.ass-page .ass__toolbar .p-button.p-button-success {
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.2);
}

/* Hero */
.ass-page .ass__hero {
  order: -10;
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem;
  width: 100%;
  margin-bottom: 1.25rem;
  padding: 1.35rem 1.5rem;
  border-radius: var(--ass-radius);
  background: linear-gradient(135deg, #4557a3 0%, #5b6fd6 55%, #7c8ce8 100%);
  color: #fff;
  box-shadow: 0 12px 40px rgba(69, 87, 163, 0.25);
}

.ass-page .ass__hero-main {
  flex: 1 1 240px;
  min-width: 0;
}

.ass-page .ass__eyebrow {
  display: block;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.85;
  margin-bottom: 0.35rem;
}

.ass-page .ass__hero h1 {
  margin: 0 0 0.4rem;
  font-size: clamp(1.2rem, 2.5vw, 1.55rem);
  font-weight: 800;
  line-height: 1.25;
}

.ass-page .ass__hero-sub {
  margin: 0;
  font-size: 0.92rem;
  opacity: 0.92;
  line-height: 1.5;
}

.ass-page .ass__hero-meta {
  flex: 0 0 auto;
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: center;
}

.ass-page .ass__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  white-space: nowrap;
  background: rgba(255, 255, 255, 0.16);
  border: 1px solid rgba(255, 255, 255, 0.28);
  color: #fff;
}

.ass-page .ass__chip i {
  font-size: 0.82rem;
  opacity: 0.9;
}

/* Liste kartı */
.ass-page .ass__list-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--ass-surface);
  border: 1px solid var(--ass-border);
  border-radius: var(--ass-radius);
  box-shadow: var(--ass-shadow);
  overflow: hidden;
}

.ass-page .ass__list-card > .form-container,
.ass-page .ass__list-card .form-container {
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ass-page .ass__list-head {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--ass-border);
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
}

.ass-page .ass__list-head-icon {
  flex: 0 0 auto;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 1rem;
}

.ass-page .ass__list-head h2 {
  margin: 0 0 0.15rem;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ass-text);
}

.ass-page .ass__list-head p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ass-label);
  line-height: 1.4;
}

/* Tablo */
.ass-page .ass__inventory {
  padding: 0;
}

.ass-page .ass-table-wrap {
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.ass-page .ass-table {
  width: 100%;
  border-collapse: collapse;
  font-size: 0.88rem;
}

.ass-page .ass-table thead {
  background: var(--ass-soft);
  border-bottom: 2px solid var(--ass-border);
}

.ass-page .ass-table th {
  padding: 0.85rem 1.15rem;
  text-align: left;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ass-label);
  white-space: nowrap;
}

.ass-page .ass-table th.ass-table__qty,
.ass-page .ass-table td.ass-table__qty {
  text-align: right;
  width: 7rem;
}

.ass-page .ass-table th.ass-table__num,
.ass-page .ass-table td.ass-table__num {
  width: 3.25rem;
  text-align: center;
  color: var(--ass-muted);
  font-weight: 700;
  font-size: 0.78rem;
}

.ass-page .ass-table tbody {
  counter-reset: ass-row;
}

.ass-page .ass-table tbody .ass-table__num::before {
  counter-increment: ass-row;
  content: counter(ass-row);
}

.ass-page .ass-table__row {
  border-bottom: 1px solid #f1f5f9;
  transition: background 0.12s ease;
}

.ass-page .ass-table__row:hover {
  background: #f8fafc;
}

.ass-page .ass-table__row:last-child {
  border-bottom: none;
}

.ass-page .ass-table td {
  padding: 0.9rem 1.15rem;
  vertical-align: middle;
}

.ass-page .ass-table__link {
  display: inline-flex;
  align-items: flex-start;
  gap: 0.55rem;
  max-width: 100%;
  text-decoration: none;
  color: var(--ass-primary);
  font-weight: 700;
  line-height: 1.45;
  transition: color 0.12s ease;
}

.ass-page .ass-table__link:hover {
  color: var(--ass-accent);
}

.ass-page .ass-table__link-icon {
  flex: 0 0 auto;
  width: 1.75rem;
  height: 1.75rem;
  margin-top: 0.05rem;
  border-radius: 8px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.78rem;
}

.ass-page .ass-table__link-text {
  flex: 1 1 auto;
  min-width: 0;
  word-break: break-word;
}

.ass-page .ass-table__link-arrow {
  flex: 0 0 auto;
  margin-top: 0.2rem;
  font-size: 0.68rem;
  opacity: 0;
  transform: translateX(-2px);
  transition: opacity 0.12s ease, transform 0.12s ease;
}

.ass-page .ass-table__link:hover .ass-table__link-arrow {
  opacity: 0.7;
  transform: translateX(0);
}

.ass-page .ass-qty-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 2.5rem;
  padding: 0.35rem 0.65rem;
  border-radius: 999px;
  background: #eef2ff;
  color: var(--ass-primary);
  font-size: 0.86rem;
  font-weight: 800;
  line-height: 1;
}

.ass-page .ass__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 0.65rem;
  padding: 3rem 1.5rem;
  text-align: center;
  color: var(--ass-muted);
}

.ass-page .ass__empty i {
  font-size: 2rem;
  opacity: 0.55;
}

.ass-page .ass__empty p {
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--ass-label);
}

/* Eski loop/grid kalıntılarını gizle */
.ass-page .ass__list-card .loop,
.ass-page .ass__list-card .grid.ass__legacy-row {
  display: none !important;
}

@media (max-width: 767px) {
  .ass-page .ass__hero {
    padding: 1.1rem 1.15rem;
  }

  .ass-page .ass-table thead {
    display: none;
  }

  .ass-page .ass-table,
  .ass-page .ass-table tbody,
  .ass-page .ass-table tr,
  .ass-page .ass-table td {
    display: block;
    width: 100%;
  }

  .ass-page .ass-table__row {
    padding: 0.85rem 1rem;
    border-bottom: 1px solid var(--ass-border);
  }

  .ass-page .ass-table__row:hover {
    background: #fff;
  }

  .ass-page .ass-table td {
    padding: 0.25rem 0;
    text-align: left !important;
    width: 100% !important;
  }

  .ass-page .ass-table td.ass-table__num {
    display: none;
  }

  .ass-page .ass-table td.ass-table__qty {
    margin-top: 0.35rem;
  }

  .ass-page .ass-table td::before {
    content: attr(data-label);
    display: block;
    font-size: 0.64rem;
    font-weight: 800;
    letter-spacing: 0.05em;
    text-transform: uppercase;
    color: var(--ass-muted);
    margin-bottom: 0.2rem;
  }

  .ass-page .ass-table td.ass-table__name::before {
    display: none;
  }
}

@media print {
  .ass-page {
    background: #fff;
    padding: 0;
  }

  .ass-page .ass__toolbar {
    display: none !important;
  }

  .ass-page .ass__hero {
    box-shadow: none;
    border-radius: 0;
    print-color-adjust: exact;
    -webkit-print-color-adjust: exact;
  }

  .ass-page .ass__list-card {
    box-shadow: none;
    border: 1px solid #ddd;
  }

  .ass-page .ass-table__link {
    color: #000;
  }

  .ass-page .ass-table__link-arrow {
    display: none;
  }
}

/* Kayıp Raporu Detayı — ürün hero + form kartı */
.ass-page .ass__hero--product {
  display: grid;
  grid-template-columns: auto 1fr auto;
  align-items: center;
  gap: 1rem 1.25rem;
}

.ass-page .ass__hero-media {
  flex: 0 0 auto;
  grid-row: 1;
  grid-column: 1;
}

.ass-page .ass__hero--product .ass__hero-main {
  grid-row: 1;
  grid-column: 2;
  min-width: 0;
}

.ass-page .ass__hero-status {
  flex: 0 0 auto;
  display: flex;
  align-items: center;
  align-self: flex-start;
  grid-row: 1;
  grid-column: 3;
}

.ass-page .ass__badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.5rem 0.9rem;
  border-radius: 999px;
  font-size: 0.78rem;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
}

.ass-page .ass__badge i {
  font-size: 0.82rem;
  line-height: 1;
  flex: 0 0 auto;
}

.ass-page .ass__badge--done {
  background: rgba(255, 255, 255, 0.18);
  border: 1px solid rgba(255, 255, 255, 0.35);
  color: #fff;
}

.ass-page .ass__badge--pending {
  background: rgba(251, 191, 36, 0.28);
  border: 1px solid rgba(253, 224, 71, 0.55);
  color: #fff;
  box-shadow: 0 2px 10px rgba(15, 23, 42, 0.12);
}

.ass-page .ass__hero-img {
  width: 5.5rem;
  height: 5.5rem;
  object-fit: cover;
  border-radius: 14px;
  border: 3px solid rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.12);
  box-shadow: 0 8px 24px rgba(15, 23, 42, 0.18);
}

.ass-page .ass__hero-meta-line {
  margin: 0.35rem 0 0;
  font-size: 0.86rem;
  opacity: 0.92;
  line-height: 1.5;
}

.ass-page .ass__hero-meta-line i {
  font-size: 0.82rem;
  margin-right: 0.15rem;
}

/* Detay form kartı */
.ass-page .ass__detail-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: hidden;
}

.ass-page .ass__detail-card > .form-container,
.ass-page .ass__detail-card .form-container {
  padding: 0 1.15rem 1.25rem !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ass-page .ass__detail-card .form-container > label,
.ass-page .ass__detail-card .form-container > .condition {
  display: block;
  padding: 0.85rem 0;
  border-bottom: 1px solid #f1f5f9;
}

.ass-page .ass__detail-card .form-container > label:last-child,
.ass-page .ass__detail-card .form-container > .condition:last-child {
  border-bottom: none;
}

.ass-page .ass__detail-card .form-container label,
.ass-page .ass__detail-card .form-container .label {
  color: #64748b !important;
  font-size: 0.72rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.ass-page .ass__detail-card .form-container .label + span,
.ass-page .ass__detail-card .form-container .label ~ .value,
.ass-page .ass__detail-card .form-container label ~ span:not(.label) {
  color: #1e293b !important;
  font-size: 0.92rem !important;
  font-weight: 600 !important;
  line-height: 1.45;
}

.ass-page .ass__detail-card .form-fields-container {
  margin-top: 0.5rem;
  padding: 1rem 0 0;
  border-top: 1px dashed #e2e8f0;
}

.ass-page .ass__detail-card .form-fields-container > label,
.ass-page .ass__detail-card .form-fields-container .label {
  display: block;
  margin-bottom: 0.65rem;
  color: #64748b !important;
  font-size: 0.72rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.ass-page .ass__detail-card .image-lightbox,
.ass-page .ass__detail-card .form-fields-container img {
  border-radius: 10px;
}

.ass-page .ass__detail-card .p-button-success,
.ass-page .ass__detail-card .p-button.p-button-success {
  border-radius: 10px;
  font-weight: 700;
  min-height: 2.5rem;
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.25);
}

.ass-page .ass__detail-card .form-container .condition .condition {
  padding: 0;
  border-bottom: none;
}

@media (min-width: 768px) {
  .ass-page .ass__hero-img {
    width: 6.5rem;
    height: 6.5rem;
  }

  .ass-page .ass__detail-card .form-container {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 0 1.5rem;
    padding: 0 1.35rem 1.35rem !important;
  }

  .ass-page .ass__detail-card .form-container > .form-fields-container,
  .ass-page .ass__detail-card .form-container > .condition:last-of-type,
  .ass-page .ass__detail-card .form-container > .condition:nth-last-child(2) {
    grid-column: 1 / -1;
  }
}

@media (max-width: 767px) {
  .ass-page .ass__hero--product {
    grid-template-columns: auto 1fr;
    grid-template-areas:
      'media main'
      'status status';
    align-items: start;
  }

  .ass-page .ass__hero-media {
    grid-area: media;
  }

  .ass-page .ass__hero--product .ass__hero-main {
    grid-area: main;
  }

  .ass-page .ass__hero-status {
    grid-area: status;
    width: 100%;
    justify-content: flex-start;
    margin-top: 0.15rem;
  }
}

@media print {
  .ass-page .ass__toolbar {
    display: none !important;
  }

  .ass-page .ass__detail-card .p-button-success {
    display: none !important;
  }
}

/* Transfer Detayı — hero, detay kartı, şoför işlem kartları */

.ass-page .ass__hero--transfer .ass__hero-meta-line {
  margin: 0.35rem 0 0;
}

/* Durum rozetleri (form içi) */
.ass-page .ass__detail-card .form-container > .condition .label,
.ass-page .ass__detail-card .form-container > label .label {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  padding: 0.3rem 0.7rem;
  border-radius: 999px;
  font-size: 0.75rem !important;
  font-weight: 700 !important;
  letter-spacing: 0;
  text-transform: none !important;
}

/* Şoför işlem kartları */
.ass-page .ass__action-card {
  width: 100%;
  margin-bottom: 1.25rem;
  background: var(--ass-surface, #fff);
  border: 1px solid var(--ass-border, #e2e8f0);
  border-radius: var(--ass-radius, 16px);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
  overflow: hidden;
}

.ass-page .ass__action-card > .condition,
.ass-page .ass__action-card .condition {
  padding: 0 1.15rem 1.25rem;
  margin: 0;
  border: none;
}

.ass-page .ass__action-card .form-container {
  padding: 0 !important;
  margin: 0 !important;
  border: none !important;
  box-shadow: none !important;
  background: transparent !important;
}

.ass-page .ass__action-card .form-container label,
.ass-page .ass__action-card .form-container .label {
  color: #64748b !important;
  font-size: 0.72rem !important;
  font-weight: 800 !important;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.ass-page .ass__action-card .p-button,
.ass-page .ass__action-card .p-button-success,
.ass-page .ass__action-card .p-button.p-button-success {
  border-radius: 10px;
  font-weight: 700;
  min-height: 2.5rem;
  box-shadow: 0 4px 14px rgba(34, 197, 94, 0.22);
}

.ass-page .ass__action-card .input-text,
.ass-page .ass__action-card input.p-inputtext,
.ass-page .ass__action-card textarea {
  border-radius: 10px;
}

.ass-page .ass__action-head {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  padding: 1.1rem 1.25rem;
  border-bottom: 1px solid var(--ass-border, #e2e8f0);
  background: linear-gradient(180deg, #f8fafc 0%, #fff 100%);
}

.ass-page .ass__action-head-icon {
  flex: 0 0 auto;
  width: 2.5rem;
  height: 2.5rem;
  border-radius: 12px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary, #4557a3);
  font-size: 1rem;
}

.ass-page .ass__action-head h2 {
  margin: 0 0 0.15rem;
  font-size: 1.05rem;
  font-weight: 800;
  color: var(--ass-text, #1e293b);
}

.ass-page .ass__action-head p {
  margin: 0;
  font-size: 0.82rem;
  color: var(--ass-label, #64748b);
  line-height: 1.4;
}

@media print {
  .ass-page .ass__action-card {
    box-shadow: none;
    border: 1px solid #ddd;
  }

  .ass-page .ass__action-card .p-button {
    display: none !important;
  }
}

/* transfer-detay-beta — durum banner, görsel, işlem kartları */

.ass-page .tdb-status-wrap {
  width: 100%;
  margin: 0 0 1rem;
}

.ass-page .tdb-status {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  justify-content: space-between;
  gap: 1rem 1.25rem;
  padding: 1.15rem 1.35rem;
  border-radius: var(--ass-radius, 16px);
  border: 1px solid var(--ass-border, #e2e8f0);
  background: linear-gradient(135deg, #ffffff 0%, #f8fafc 100%);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
}

.tdb-status__main {
  flex: 1 1 280px;
  min-width: 0;
}

.tdb-status__eyebrow {
  display: block;
  margin-bottom: 0.45rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ass-label, #64748b);
}

.tdb-status__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 0.55rem;
}

.tdb-badge {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  font-size: 0.8rem;
  font-weight: 700;
  line-height: 1.2;
  white-space: nowrap;
}

.tdb-badge i {
  font-size: 0.85rem;
}

.tdb-badge--pending {
  background: #fff7ed;
  color: #c2410c;
  border: 1px solid #fed7aa;
}

.tdb-badge--done {
  background: #ecfdf5;
  color: #15803d;
  border: 1px solid #bbf7d0;
}

.tdb-badge--danger {
  background: #fef2f2;
  color: #b91c1c;
  border: 1px solid #fecaca;
}

.tdb-badge--cargo {
  background: #f5f3ff;
  color: #6d28d9;
  border: 1px solid #ddd6fe;
}

.tdb-badge--transit {
  background: #eff6ff;
  color: #1d4ed8;
  border: 1px solid #bfdbfe;
}

.tdb-status__hint {
  margin: 0.65rem 0 0;
  max-width: 42rem;
  font-size: 0.84rem;
  line-height: 1.5;
  color: var(--ass-label, #64748b);
}

.tdb-status__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  align-items: flex-start;
}

.tdb-status__chip {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  padding: 0.4rem 0.75rem;
  border-radius: 10px;
  background: #eef2ff;
  color: #4338ca;
  font-size: 0.76rem;
  font-weight: 700;
}

.tdb-steps {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  width: 100%;
  margin-top: 0.35rem;
  padding-top: 0.85rem;
  border-top: 1px dashed var(--ass-border, #e2e8f0);
}

.tdb-step {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  padding: 0.35rem 0.7rem;
  border-radius: 999px;
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ass-label, #64748b);
  background: #f8fafc;
  border: 1px solid #e2e8f0;
}

.tdb-step__num {
  width: 1.35rem;
  height: 1.35rem;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-size: 0.68rem;
  background: #e2e8f0;
  color: #475569;
}

.tdb-step--active {
  color: #4338ca;
  background: #eef2ff;
  border-color: #c7d2fe;
}

.tdb-step--active .tdb-step__num {
  background: #4338ca;
  color: #fff;
}

.tdb-step--done {
  color: #15803d;
  background: #ecfdf5;
  border-color: #bbf7d0;
}

.tdb-step--done .tdb-step__num {
  background: #16a34a;
  color: #fff;
}

/* Transfer görseli */
.ass-page .tdb-visual {
  width: 100%;
  margin: 0 0 1rem;
  padding: 1.25rem 1.35rem;
  border-radius: var(--ass-radius, 16px);
  border: 1px solid var(--ass-border, #e2e8f0);
  background: var(--ass-surface, #fff);
  box-shadow: var(--ass-shadow, 0 4px 24px rgba(69, 87, 163, 0.08));
}

.tdb-visual__route {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto minmax(0, 1fr);
  gap: 1rem;
  align-items: center;
  margin-bottom: 1.15rem;
}

.tdb-visual__node {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 0.35rem;
}

.tdb-visual__icon {
  width: 3rem;
  height: 3rem;
  border-radius: 14px;
  display: grid;
  place-items: center;
  background: #eef2ff;
  color: var(--ass-primary, #4557a3);
  font-size: 1.2rem;
  flex-shrink: 0;
}

.tdb-visual__icon .pi {
  display: inline-block;
  line-height: 1;
  font-family: 'primeicons' !important;
  font-size: 1.25rem;
  color: inherit;
}

.tdb-visual__node--from .tdb-visual__icon {
  background: #eef2ff;
  color: #4338ca;
}

.tdb-visual__node--to .tdb-visual__icon {
  background: #ecfdf5;
  color: #16a34a;
}

.tdb-visual__label {
  font-size: 0.92rem;
  font-weight: 800;
  color: var(--ass-text, #1e293b);
  line-height: 1.3;
}

.tdb-visual__tag {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: var(--ass-label, #64748b);
}

.tdb-visual__lane {
  position: relative;
  min-width: 7rem;
  display: flex;
  justify-content: center;
  align-items: center;
}

.tdb-visual__line {
  position: absolute;
  left: 0;
  right: 0;
  top: 50%;
  height: 2px;
  background: linear-gradient(90deg, #cbd5e1 0%, #94a3b8 50%, #cbd5e1 100%);
}

.tdb-visual__carrier {
  position: relative;
  z-index: 1;
  display: inline-flex;
  flex-direction: column;
  align-items: center;
  gap: 0.25rem;
  padding: 0.55rem 0.8rem;
  border-radius: 12px;
  background: #fff;
  border: 1px solid var(--ass-border, #e2e8f0);
  box-shadow: 0 6px 18px rgba(15, 23, 42, 0.08);
  font-size: 0.72rem;
  font-weight: 700;
  color: var(--ass-text, #1e293b);
}

.tdb-visual__carrier i {
  font-size: 1.15rem;
}

.tdb-visual__carrier--cargo {
  color: #6d28d9;
}

.tdb-visual__carrier--driver {
  color: #c2410c;
}

.tdb-visual__details {
  display: grid;
  grid-template-columns: 1.4fr repeat(4, minmax(0, 1fr));
  gap: 0.85rem 1rem;
  padding-top: 1rem;
  border-top: 1px solid #f1f5f9;
}

.tdb-visual__product {
  display: flex;
  align-items: center;
  gap: 0.85rem;
  min-width: 0;
}

.tdb-visual__img {
  width: 3.5rem;
  height: 3.5rem;
  object-fit: cover;
  border-radius: 12px;
  border: 1px solid var(--ass-border, #e2e8f0);
  background: #f8fafc;
}

.tdb-visual__detail-label {
  display: block;
  margin-bottom: 0.2rem;
  font-size: 0.68rem;
  font-weight: 800;
  letter-spacing: 0.05em;
  text-transform: uppercase;
  color: var(--ass-label, #64748b);
}

.tdb-visual__stat strong,
.tdb-visual__product strong {
  font-size: 0.9rem;
  color: var(--ass-text, #1e293b);
  line-height: 1.35;
}

/* İşlem kartları yığını */
.ass-page .ass__actions-stack {
  display: flex;
  flex-direction: column;
  gap: 1rem;
  width: 100%;
  margin-top: 0.25rem;
}

.ass-page .ass__actions-stack > .ass__action-card,
.ass-page .ass__actions-stack > .condition {
  width: 100%;
  margin: 0;
}

.ass-page .ass__actions-stack .ass__action-card--approval > .condition {
  padding: 1.15rem 1.35rem 1.35rem;
}

.ass-page .ass__actions-stack .ass__action-card--approval .condition .condition {
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.85rem;
}

.ass-page .ass__actions-stack .ass__action-card--approval .form-container,
.ass-page .ass__actions-stack .ass__action-card--cargo .form-container,
.ass-page .ass__actions-stack .ass__action-card:not(.ass__action-card--approval) .form-container {
  margin: 0 !important;
  padding: 1rem 1.1rem !important;
  background: #f8fafc !important;
  border: 1px solid var(--ass-border, #e2e8f0) !important;
  border-radius: 12px !important;
  box-shadow: none !important;
}

.ass-page .ass__actions-stack .ass__action-card--cargo .ass__action-head-icon,
.ass-page .ass__actions-stack .ass__action-card--cargo.ass__action-card--depart .ass__action-head-icon {
  background: #fff7ed;
  color: #c2410c;
}

.ass-page .ass__actions-stack .ass__action-card--cargo.ass__action-card--arrive .ass__action-head-icon {
  background: #f5f3ff;
  color: #6d28d9;
}

.ass-page .ass__actions-stack .ass__action-card .form-fields-container {
  display: grid;
  grid-template-columns: 1fr;
  gap: 0.85rem;
  width: 100%;
}

.ass-page .ass__actions-stack .ass__action-card .form-fields-container label,
.ass-page .ass__actions-stack .ass__action-card .form-container .label {
  display: block !important;
  margin-bottom: 0.45rem !important;
}

.ass-page .ass__actions-stack .ass__action-card input.p-inputtext,
.ass-page .ass__actions-stack .ass__action-card textarea {
  width: 100% !important;
  max-width: none !important;
  min-height: 2.75rem;
}

.ass-page .ass__actions-stack .ass__action-card .p-button,
.ass-page .ass__actions-stack .ass__action-card .p-button-success,
.ass-page .ass__actions-stack .ass__action-card .p-button.p-button-success,
.ass-page .ass__actions-stack .ass__action-card .p-button-danger,
.ass-page .ass__actions-stack .ass__action-card .p-button.p-button-danger,
.ass-page .ass__actions-stack .ass__action-card .p-button-warning,
.ass-page .ass__actions-stack .ass__action-card .p-button.p-button-warning {
  width: 100%;
  min-height: 2.6rem;
}

.ass-page .ass__actions-stack .ass__action-card .p-button-danger,
.ass-page .ass__actions-stack .ass__action-card .p-button.p-button-danger {
  box-shadow: 0 4px 14px rgba(239, 68, 68, 0.22);
}

.ass-page .ass__actions-stack .ass__action-card:not(.ass__action-card--approval) > .condition,
.ass-page .ass__actions-stack .ass__action-card:not(.ass__action-card--approval) .condition {
  padding: 0 1.25rem 1.25rem;
}

@media (min-width: 720px) {
  .ass-page .ass__actions-stack .ass__action-card .form-fields-container {
    grid-template-columns: minmax(0, 1fr) auto;
    align-items: end;
    column-gap: 1rem;
  }

  .ass-page .ass__actions-stack .ass__action-card .form-fields-container > .input-text {
    grid-column: 1;
  }

  .ass-page .ass__actions-stack .ass__action-card .form-fields-container > .button {
    grid-column: 2;
    width: auto;
    min-width: 9rem;
  }

  .ass-page .ass__actions-stack .ass__action-card .p-button,
  .ass-page .ass__actions-stack .ass__action-card .p-button-success,
  .ass-page .ass__actions-stack .ass__action-card .p-button.p-button-success,
  .ass-page .ass__actions-stack .ass__action-card .p-button-danger,
  .ass-page .ass__actions-stack .ass__action-card .p-button.p-button-danger,
  .ass-page .ass__actions-stack .ass__action-card .p-button-warning,
  .ass-page .ass__actions-stack .ass__action-card .p-button.p-button-warning {
    width: auto;
    min-width: 9rem;
  }
}

@media (max-width: 900px) {
  .tdb-visual__route {
    grid-template-columns: 1fr;
    gap: 0.85rem;
  }

  .tdb-visual__lane {
    min-width: 0;
    padding: 0.5rem 0;
  }

  .tdb-visual__line {
    display: none;
  }

  .tdb-visual__details {
    grid-template-columns: 1fr 1fr;
  }

  .tdb-visual__product {
    grid-column: 1 / -1;
  }
}

@media (max-width: 560px) {
  .tdb-visual__details {
    grid-template-columns: 1fr;
  }
}
